class Item { public int Number { get; set; } }
class Holder {
    public Item Child { get; }
    private int stored;
    public int Restricted { private get => stored; set { stored = value; } }
    public int WriteOnly { set { if (value < 0) return; stored = value; } }
    public Holder(Item item) { Child = item; }
    public int Read() => Restricted;
}
void Main() {
    var item = new Item(); var h = new Holder(item); h.Child.Number += 3;
    Print(item.Number); Print(h.Child == item);
    Print(h.WriteOnly = -2); Print(h.Read());
    h.Restricted = 8; Print(h.Read()); h.WriteOnly = 9; Print(h.Read());
}
